CREATE DATABASE IF NOT EXISTS ai_crm CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ai_crm;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE leads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(190) DEFAULT NULL,phone VARCHAR(40) DEFAULT NULL,company VARCHAR(160) DEFAULT NULL,source VARCHAR(50) NOT NULL DEFAULT 'website',status ENUM('new','contacted','qualified','proposal','won','lost') NOT NULL DEFAULT 'new',value DECIMAL(12,2) NOT NULL DEFAULT 0,follow_up_at DATETIME DEFAULT NULL,notes TEXT,ai_score TINYINT UNSIGNED DEFAULT NULL,ai_priority ENUM('hot','warm','cold') DEFAULT NULL,ai_summary TEXT,ai_next_action TEXT,ai_analyzed_at DATETIME DEFAULT NULL,created_by BIGINT UNSIGNED DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_leads_status(status),INDEX idx_leads_followup(follow_up_at),INDEX idx_leads_score(ai_score),CONSTRAINT fk_leads_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE activities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lead_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED DEFAULT NULL,type ENUM('note','call','email','whatsapp','meeting','task') NOT NULL,description TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_activity_lead(lead_id,created_at),CONSTRAINT fk_activity_lead FOREIGN KEY(lead_id) REFERENCES leads(id) ON DELETE CASCADE,CONSTRAINT fk_activity_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE ai_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lead_id BIGINT UNSIGNED NOT NULL,agent VARCHAR(80) NOT NULL,score TINYINT UNSIGNED,priority VARCHAR(20),summary TEXT,next_action TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_ai_lead(lead_id,created_at),CONSTRAINT fk_ai_lead FOREIGN KEY(lead_id) REFERENCES leads(id) ON DELETE CASCADE) ENGINE=InnoDB;
